-- Squashed from 5 prior migrations (see git log) on 2026-05-04.
-- App: video-conferencing. Generated by scripts/phase4-squash-app.mjs from a
-- pg_dump --schema-only of a freshly-migrated flagship_video_conferencing DB.
--
-- This is a hand-derived baseline migration: it captures the verified-
-- green schema produced by the prior multi-file migration set, in a
-- single replayable file. `mlcl create <app>` will scaffold this as
-- migration 0010 and the runtime migration runner will apply it as a
-- single transaction at first boot.
--
-- IDEMPOTENCY: the runtime migrator (`@molecule/api-database-postgresql`
-- `createMigrator`) runs each .sql file as ONE implicit transaction and, on
-- error, logs `⚠` and CONTINUES — its contract is "IF NOT EXISTS DDL is
-- idempotent, so re-running is safe." A bare `CREATE TABLE`/`CREATE INDEX`
-- that hits an already-existing object throws and rolls back the ENTIRE file,
-- leaving the schema half-built (e.g. `devices` missing → signup 500s with
-- `relation "devices" does not exist` at device.createOrUpdate). So every
-- CREATE here MUST use `IF NOT EXISTS`, and constraints are declared INLINE
-- (folded into CREATE TABLE) rather than via separate `ALTER TABLE ADD
-- CONSTRAINT`, which has no IF NOT EXISTS and would re-throw on re-run.
CREATE TABLE IF NOT EXISTS public.devices (
    id uuid NOT NULL,
    "createdAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "userId" uuid NOT NULL,
    name text,
    "pushPlatform" text,
    "pushSubscription" jsonb,
    "hasPushSubscription" boolean,
    CONSTRAINT devices_pkey PRIMARY KEY (id)
);


--
-- Name: meeting_chat; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.meeting_chat (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    meeting_id uuid NOT NULL,
    user_id uuid,
    guest_name text,
    content text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone,
    CONSTRAINT meeting_chat_pkey PRIMARY KEY (id)
);


--
-- Name: meeting_invites; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.meeting_invites (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    meeting_id uuid NOT NULL,
    invitee_email text NOT NULL,
    invitee_user_id uuid,
    token text NOT NULL,
    sent_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone,
    CONSTRAINT meeting_invites_pkey PRIMARY KEY (id),
    CONSTRAINT meeting_invites_token_key UNIQUE (token)
);


--
-- Name: meeting_participants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.meeting_participants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    meeting_id uuid NOT NULL,
    user_id uuid,
    guest_name text,
    role text DEFAULT 'attendee'::text NOT NULL,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    left_at timestamp with time zone,
    audio_enabled boolean DEFAULT true NOT NULL,
    video_enabled boolean DEFAULT true NOT NULL,
    screen_sharing boolean DEFAULT false NOT NULL,
    hand_raised boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone,
    CONSTRAINT meeting_participants_pkey PRIMARY KEY (id)
);


--
-- Name: meetings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.meetings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid,
    host_id uuid NOT NULL,
    title text NOT NULL,
    description text,
    status text DEFAULT 'scheduled'::text NOT NULL,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    is_recurring boolean DEFAULT false NOT NULL,
    recurrence_rule text,
    join_code text NOT NULL,
    password_hash text,
    waiting_room_enabled boolean DEFAULT true NOT NULL,
    max_participants integer DEFAULT 10 NOT NULL,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone,
    "updatedAt" timestamp with time zone,
    CONSTRAINT meetings_pkey PRIMARY KEY (id),
    CONSTRAINT meetings_join_code_key UNIQUE (join_code)
);


--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    type text NOT NULL,
    title text NOT NULL,
    body text,
    data jsonb,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT notifications_pkey PRIMARY KEY (id)
);


--
-- Name: recordings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.recordings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    meeting_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    video_url text NOT NULL,
    thumbnail_url text,
    duration_ms bigint DEFAULT 0 NOT NULL,
    size_bytes bigint DEFAULT 0 NOT NULL,
    status text DEFAULT 'ready'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone,
    CONSTRAINT recordings_pkey PRIMARY KEY (id)
);


--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.users (
    id uuid NOT NULL,
    "createdAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    username character varying(255),
    name text,
    email character varying(1023),
    "twoFactorEnabled" boolean DEFAULT false,
    "oauthServer" text,
    "oauthId" text,
    "oauthData" jsonb,
    "planKey" text,
    "planExpiresAt" timestamp with time zone,
    "planAutoRenews" boolean DEFAULT false,
    CONSTRAINT users_pkey PRIMARY KEY (id),
    CONSTRAINT users_email_key UNIQUE (email)
);


--
-- Name: usersSecrets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public."usersSecrets" (
    id uuid NOT NULL,
    "passwordHash" text,
    "passwordResetToken" text,
    "passwordResetTokenAt" timestamp with time zone,
    "pendingTwoFactorSecret" text,
    "twoFactorSecret" text,
    CONSTRAINT "usersSecrets_pkey" PRIMARY KEY (id)
);


--
-- Name: workspace_members; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.workspace_members (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text DEFAULT 'member'::text NOT NULL,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone,
    CONSTRAINT workspace_members_pkey PRIMARY KEY (id)
);


--
-- Name: workspaces; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.workspaces (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    plan_key text DEFAULT 'free'::text NOT NULL,
    seat_limit integer DEFAULT 5 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone,
    "updatedAt" timestamp with time zone,
    CONSTRAINT workspaces_pkey PRIMARY KEY (id),
    CONSTRAINT workspaces_slug_key UNIQUE (slug)
);


--
-- Indexes
--

CREATE INDEX IF NOT EXISTS "devices_createdAt_index" ON public.devices USING btree ("createdAt");


CREATE INDEX IF NOT EXISTS "devices_updatedAt_index" ON public.devices USING btree ("updatedAt");


CREATE INDEX IF NOT EXISTS "devices_userId_index" ON public.devices USING btree ("userId");


CREATE INDEX IF NOT EXISTS meeting_chat_meeting_id_idx ON public.meeting_chat USING btree (meeting_id, created_at);


CREATE INDEX IF NOT EXISTS meeting_invites_email_idx ON public.meeting_invites USING btree (invitee_email);


CREATE INDEX IF NOT EXISTS meeting_invites_meeting_id_idx ON public.meeting_invites USING btree (meeting_id);


CREATE INDEX IF NOT EXISTS meeting_participants_meeting_id_idx ON public.meeting_participants USING btree (meeting_id, joined_at);


CREATE INDEX IF NOT EXISTS meeting_participants_user_id_idx ON public.meeting_participants USING btree (user_id);


CREATE INDEX IF NOT EXISTS meetings_host_id_starts_at_idx ON public.meetings USING btree (host_id, starts_at DESC);


CREATE INDEX IF NOT EXISTS meetings_status_idx ON public.meetings USING btree (status);


CREATE INDEX IF NOT EXISTS meetings_workspace_starts_at_idx ON public.meetings USING btree (workspace_id, starts_at);


CREATE INDEX IF NOT EXISTS notifications_user_id_created_at_idx ON public.notifications USING btree (user_id, created_at DESC);


CREATE INDEX IF NOT EXISTS notifications_user_id_unread_idx ON public.notifications USING btree (user_id) WHERE (read_at IS NULL);


CREATE INDEX IF NOT EXISTS recordings_meeting_id_idx ON public.recordings USING btree (meeting_id);


CREATE INDEX IF NOT EXISTS recordings_owner_id_idx ON public.recordings USING btree (owner_id);


CREATE INDEX IF NOT EXISTS "users_createdAt_index" ON public.users USING btree ("createdAt");


CREATE INDEX IF NOT EXISTS users_email_index ON public.users USING btree (email);


CREATE INDEX IF NOT EXISTS "users_updatedAt_index" ON public.users USING btree ("updatedAt");


CREATE INDEX IF NOT EXISTS users_username_index ON public.users USING btree (username);


CREATE UNIQUE INDEX IF NOT EXISTS workspace_members_unique_idx ON public.workspace_members USING btree (workspace_id, user_id);


CREATE INDEX IF NOT EXISTS workspace_members_user_id_idx ON public.workspace_members USING btree (user_id);


CREATE INDEX IF NOT EXISTS workspaces_owner_id_idx ON public.workspaces USING btree (owner_id);
